const prioritySort={key:'criticality_score',dir:-1};function priorityVal(x,k){if(['criticality_score','days_since_last','failed_count'].includes(k))return Number(x[k]??-1);return String(x[k]??'').toLocaleLowerCase('pt-BR')}function renderPriorities(base){if(!$('priorityRows'))return;const rows=base.filter(x=>x.criticality!=='NORMAL'||Number(x.failed_count||0)>0).sort((a,b)=>{const av=priorityVal(a,prioritySort.key),bv=priorityVal(b,prioritySort.key);if(typeof av==='number')return (av-bv)*prioritySort.dir;return av.localeCompare(bv,'pt-BR',{numeric:true,sensitivity:'base'})*prioritySort.dir});$('priorityRows').innerHTML=rows.map(x=>{const action=x.criticality_reason==='MANUTENCAO'?'Acionar manutenção do cofre antes do reagendamento':x.criticality_reason==='ACESSO_SUPORTE'?'Regularizar acesso/suporte e reagendar':Number(x.failed_count||0)>0?'Priorizar reagendamento':'Acompanhar próxima coleta';return `<tr class="${x.criticality==='CRITICA'?'dashRowCritical':x.criticality==='ALTA'?'dashRowHigh':'dashRowWarn'}"><td>${critBadge(x.criticality)}</td><td><b>${esc(x.terminal)}</b></td><td>${esc(x.company)}</td><td>${esc(x.line)}</td><td>${esc(x.station)}</td><td>${x.days_since_last==null?'Sem histórico':`${x.days_since_last} dia(s)`}</td><td>${Number(x.failed_count||0)}</td><td class="noteCell" title="${esc(x.last_failed_note||'')}">${esc(x.last_failed_note||'—')}</td><td><b>${esc(action)}</b></td></tr>`}).join('')||'<tr><td colspan="9">Nenhuma ATM crítica no recorte atual.</td></tr>'}
