// V80 · Monitoramento Inteligente — análises auditáveis sobre o mesmo recorte filtrado.
(()=>{
const $=id=>document.getElementById(id); if(!$('v80AiDiff'))return;
const esc=s=>String(s??'').replace(/[&<>\"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
const brl=v=>Number(v||0).toLocaleString('pt-BR',{style:'currency',currency:'BRL'});
const dbr=s=>s?new Date(s+'T12:00:00').toLocaleDateString('pt-BR'):'—';
function params(mode){const q=new URLSearchParams({mode,start:$('fStart').value,end:$('fEnd').value,company:$('fCompany').value,line:$('fLine').value,station:$('fStation').value,terminal:$('fAtm').value,status:$('fStatus').value,programming:$('fProgramming').value,difference:$('fDifference').value});return q}
function bars(rows,{money=false,kind=''}={}){rows=rows||[];if(!rows.length)return '<p class="muted">Sem dados para este gráfico.</p>';const max=Math.max(...rows.map(x=>Math.abs(Number(x.value)||0)),1);return `<div class="v80BarList">${rows.map(x=>`<div class="v80Bar ${kind}"><span class="v80BarLabel" title="${esc(x.label)}">${esc(x.label)}</span><div class="v80BarTrack"><div class="v80BarFill" style="width:${Math.max(2,Math.abs(Number(x.value)||0)/max*100)}%"></div></div><b>${money?brl(x.value):Number(x.value||0).toLocaleString('pt-BR')}</b></div>`).join('')}</div>`}
function kpi(label,value,cls=''){return `<div class="v80AiKpi ${cls}"><small>${esc(label)}</small><strong>${value}</strong></div>`}
function renderDiff(d){const s=d.summary,c=d.charts||{};return `<div class="v80AiKpis">${kpi('Coletas/ocorrências',s.collections,'ai')}${kpi('Negativas',s.negative,'neg')}${kpi('Zeradas',s.zero,'zero')}${kpi('Positivas',s.positive,'pos')}${kpi('Saldo A − D',brl(s.net_difference),Number(s.net_difference)<0?'neg':'zero')}${kpi('Diferença absoluta',brl(s.absolute_difference),'warn')}</div><div class="v80AiGrid"><section class="v80AiPanel"><h3>Leitura inteligente do período</h3>${(d.insights||[]).map(x=>`<div class="v80Insight">${esc(x)}</div>`).join('')}</section><section class="v80AiPanel"><h3>Distribuição das divergências</h3>${bars(c.difference_distribution)}</section><section class="v80AiPanel"><h3>Maiores diferenças negativas</h3>${bars(c.negative_top,{money:true,kind:'neg'})}</section><section class="v80AiPanel"><h3>Concentração absoluta por localidade</h3>${bars(c.by_station,{money:true,kind:'info'})}</section><section class="v80AiPanel"><h3>Concentração absoluta por linha</h3>${bars(c.by_line,{money:true})}</section><section class="v80AiPanel"><h3>Concentração absoluta por operadora</h3>${bars(c.by_company,{money:true,kind:'info'})}</section></div><section class="v80AiPanel" style="margin-top:14px"><h3>Casos negativos que exigem atenção</h3><div class="v80AiTable"><table><thead><tr><th>ATM</th><th>Localidade</th><th>Linha</th><th>Data</th><th>Declarado</th><th>Apurado</th><th>Diferença</th><th>% sobre declarado</th></tr></thead><tbody>${(d.negative_rows||[]).map(x=>`<tr><td><b>${esc(x.terminal)}</b></td><td>${esc(x.station)}</td><td>${esc(x.line)}</td><td>${dbr(x.date)}</td><td>${brl(x.declared_amount)}</td><td>${brl(x.processed_amount)}</td><td style="font-weight:800;color:#b91c1c">${brl(x.difference)}</td><td>${x.difference_pct==null?'—':Number(x.difference_pct).toLocaleString('pt-BR',{maximumFractionDigits:2})+'%'}</td></tr>`).join('')||'<tr><td colspan="8">Nenhuma diferença negativa no filtro atual.</td></tr>'}</tbody></table></div></section><div class="v80Method"><b>Metodologia:</b> ${esc(d.methodology?.financial||'')} A interpretação usa os resultados calculados; não recalcula valores financeiros.</div>`}
function renderOcc(d){const s=d.summary,c=d.charts||{};return `<div class="v80AiKpis">${kpi('Ocorrências analisadas',s.observations,'ai')}${kpi('Falha fechadura/cofre',s.lock_failures,'neg')}${kpi('Coletas/ocorrências',s.collections,'info')}${kpi('Negativas',s.negative,'neg')}${kpi('Zeradas',s.zero,'zero')}${kpi('Positivas',s.positive,'pos')}</div><div class="v80AiGrid"><section class="v80AiPanel"><h3>Leitura inteligente das observações</h3>${(d.insights||[]).map(x=>`<div class="v80Insight">${esc(x)}</div>`).join('')}</section><section class="v80AiPanel"><h3>Ocorrências por categoria</h3>${bars(c.occurrence_categories)}</section><section class="v80AiPanel"><h3>Localidades com falha de fechadura/cofre</h3>${bars(c.lock_locations,{kind:'neg'})}</section><section class="v80AiPanel"><h3>Contexto financeiro do mesmo recorte</h3>${bars(c.difference_distribution)}</section></div><section class="v80AiPanel" style="margin-top:14px"><h3>Ocorrências classificadas</h3><div class="v80AiTable"><table><thead><tr><th>Categoria</th><th>ATM</th><th>Localidade</th><th>Linha</th><th>Data</th><th>Status</th><th>Observação</th></tr></thead><tbody>${(d.occurrence_rows||[]).map(x=>`<tr><td><b>${esc(x.category)}</b></td><td>${esc(x.terminal)}</td><td>${esc(x.station)}</td><td>${esc(x.line)}</td><td>${dbr(x.date)}</td><td>${esc(x.status)}</td><td style="white-space:normal;min-width:280px">${esc(x.note||x.occurrence||'—')}</td></tr>`).join('')||'<tr><td colspan="7">Nenhuma observação no filtro atual.</td></tr>'}</tbody></table></div></section><div class="v80Method"><b>Metodologia:</b> ${esc(d.methodology?.occurrences||'')} Clique/consulte a tabela para auditar os registros que originaram cada categoria.</div>`}
async function open(mode){$('v80AiModal').classList.add('open');$('v80AiTitle').textContent=mode==='occurrences'?'Análise IA · Ocorrências':'Análise IA · Divergências';$('v80AiSub').textContent=`Período ${dbr($('fStart').value)} a ${dbr($('fEnd').value)} · respeitando os filtros ativos.`;$('v80AiBody').innerHTML='<div class="v80Loading">Calculando indicadores e correlações do recorte...</div>';try{const r=await fetch('/api/financeiro/coletas/v80/analise?'+params(mode),{cache:'no-store'}),d=await r.json();if(!r.ok||!d.ok)throw Error(d.error||'Falha na análise');$('v80AiBody').innerHTML=mode==='occurrences'?renderOcc(d):renderDiff(d)}catch(e){$('v80AiBody').innerHTML=`<div class="v80Insight" style="border-left-color:#dc2626">${esc(e.message||'Falha ao gerar análise.')}</div>`}}
$('v80AiDiff').onclick=()=>open('divergences');$('v80AiOcc').onclick=()=>open('occurrences');$('v80AiClose').onclick=()=>$('v80AiModal').classList.remove('open');$('v80AiModal').addEventListener('mousedown',e=>{if(e.target===$('v80AiModal'))$('v80AiModal').classList.remove('open')});
})();

