(()=>{const $=id=>document.getElementById(id);if(!$('v81SourceHealth'))return;
const br=d=>d?String(d).split('-').reverse().join('/'):'—';const dt=v=>v?new Date(v).toLocaleString('pt-BR'):'—';
async function health(){try{const q=new URLSearchParams({start:$('fStart').value,end:$('fEnd').value});const r=await fetch('/api/financeiro/coletas/v81/saude-fontes?'+q),d=await r.json();if(!d.ok)return;$('v81HealthDaily').textContent=br(d.realized);$('v81HealthR0050').textContent=dt(d.r0050);$('v81HealthTb').textContent=br(d.tbforte);$('v81HealthUntil').textContent=br(d.conciliable_until);$('v81HealthPct').textContent=`${d.completeness_pct}% · ${d.complete_cycles}/${d.realized_cycles}`;$('v81SourceHealth').classList.toggle('partial',d.completeness_pct<100)}catch(e){}}
$('fStart')?.addEventListener('change',health);$('fEnd')?.addEventListener('change',health);health();
$('v81SmartRun')?.addEventListener('click',async()=>{const q=$('v81SmartQuery').value.trim();if(!q)return;$('v81SmartResult').textContent='Interpretando…';try{const r=await fetch('/api/financeiro/coletas/v81/filtro-inteligente',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({query:q})}),d=await r.json();if(!d.ok)throw Error(d.error||'Falha');if(d.recognized===false){$('v81SmartResult').textContent='⚠ '+(d.warning||'Consulta não reconhecida. Nenhum filtro foi alterado.');return}V.status='';$('fStatus').value='';$('fDifference').value='';window.v81FieldTerminals=null;const f=d.filters||{};if(f.status)$('fStatus').value=f.status;if(f.companies?.length===1)$('fCompany').value=f.companies[0];if(f.difference_sign)$('fDifference').value=f.difference_sign;if(d.metric==='TX_APURADO')$('fDifferenceMetric').value='TA';else if(d.metric==='TX_DECLARADO')$('fDifferenceMetric').value='TD';else if(d.metric==='APURADO_DECLARADO')$('fDifferenceMetric').value='AD';if(d.monitoring_group?.terminals?.length){window.v81FieldTerminals=new Set(d.monitoring_group.terminals);$('fAtm').value=''}if(d.sort){const [k,dr]=d.sort.split(':');V.sort={key:k==='criticality'?'criticality_score':k,dir:dr==='asc'?1:-1,user:true}}$('v81SmartResult').textContent=(d.warning?`⚠ ${d.warning} · `:'')+`Entendido: ${(d.explanation||[]).join(' · ')}.`;cascade();apply()}catch(e){$('v81SmartResult').textContent=e.message}});
$('v81SmartQuery')?.addEventListener('keydown',e=>{if(e.key==='Enter')$('v81SmartRun').click()});
const modal=$('v81FieldModal');$('v81FieldOpen')?.addEventListener('click',()=>{modal.classList.add('open');loadGroups()});$('v81FieldClose')?.addEventListener('click',()=>modal.classList.remove('open'));
$('v81GroupCreate')?.addEventListener('click',async()=>{const name=$('v81GroupName').value.trim();if(!name)return;await post({action:'create_group',name});$('v81GroupName').value='';loadGroups()});
async function post(body){const r=await fetch('/api/financeiro/coletas/v81/monitoramento-campo',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}),d=await r.json();if(!d.ok)throw Error(d.error||'Falha');return d}
async function loadGroups(){const r=await fetch('/api/financeiro/coletas/v81/monitoramento-campo'),d=await r.json(),box=$('v81FieldGroups');if(!d.ok){box.textContent=d.error;return}box.innerHTML=(d.groups||[]).map(g=>`<section class="v81Group"><div class="v81GroupHead"><div><b>${g.name}</b><small> · ${g.active?'Ativo':'Encerrado'} · ${(g.members||[]).filter(x=>x.active).length} ATM(s)</small></div>${g.active?`<button class="secondary" data-endgroup="${g.id}">Encerrar grupo</button>`:''}</div>${g.active?`<div class="v81MemberAdd"><textarea id="v81ids${g.id}" placeholder="Cole os IDs das ATMs, um por linha ou separados por vírgula/espaço"></textarea><button data-add="${g.id}">Validar e adicionar</button></div>`:''}<div>${(g.members||[]).map(m=>`<div class="v81Member"><span>ATM <b>${m.terminal}</b> · ${m.active?'em monitoramento':'encerrada'}</span>${m.active?`<button class="secondary" data-endmember="${g.id}:${m.id}">Encerrar</button>`:''}</div>`).join('')}</div></section>`).join('')||'<p class="muted">Nenhum grupo criado.</p>';box.querySelectorAll('[data-add]').forEach(b=>b.onclick=async()=>{const gid=+b.dataset.add,d=await post({action:'add_members',group_id:gid,terminals:$('v81ids'+gid).value});alert(`${d.informed} informada(s) · ${d.added} adicionada(s) · ${d.existing} já existente(s) · ${d.invalid.length} não localizada(s)`);loadGroups()});box.querySelectorAll('[data-endmember]').forEach(b=>b.onclick=async()=>{const [gid,mid]=b.dataset.endmember.split(':');await post({action:'end_member',group_id:+gid,member_id:+mid});loadGroups()});box.querySelectorAll('[data-endgroup]').forEach(b=>b.onclick=async()=>{await post({action:'end_group',group_id:+b.dataset.endgroup});loadGroups()})}
})();
